-- ============================================================================
-- DEMO: The "Graph Trap" vs. The "Vector Bridge"
-- ============================================================================
-- Note: Uses a HARDCODED VECTOR (via CLOB bind variable) for "Metabolic Syndrome".
--       This bypasses the 4000-char limit for SQL literals.
-- ============================================================================

SET LINESIZE 200
SET PAGESIZE 100
SET SQLBLANKLINES ON
SET VERIFY OFF
SET FEEDBACK ON

COLUMN treatment FORMAT A30
COLUMN condition FORMAT A30
COLUMN score FORMAT 9.9999
COLUMN status FORMAT A20
COLUMN graph_concept FORMAT A30
COLUMN recommended_treatment FORMAT A30
COLUMN user_query FORMAT A20

PROMPT
PROMPT ============================================================================
PROMPT ACT 1: The "Triplet Trap" (Pure Graph Query)
PROMPT ============================================================================
PROMPT Scenario: User searches for treatments for "Metabolic Syndrome".
PROMPT Query:    MATCH (t)-[:TREATS]->(c) WHERE c.name = 'Metabolic Syndrome'
PROMPT Expectation: FAILURE (0 Rows) because the graph lacks the exact synonym.
PROMPT ============================================================================
PROMPT

SELECT 
    t.entity_name AS treatment,
    c.name AS condition,
    'FAILED' AS status
FROM 
    treatments_nodes t,
    conditions_nodes c,
    treats_edges te
WHERE 
    UPPER(c.name) = 'METABOLIC SYNDROME'
    AND te.to_node_id = c.node_id
    AND te.from_node_id = t.node_id;

PROMPT 
PROMPT (If no rows appeared above, the Pure Graph approach FAILED as expected.)
PROMPT

PROMPT ============================================================================
PROMPT ACT 2: The "Vector Bridge" (Hybrid Fusion Solution)
PROMPT ============================================================================
PROMPT Scenario: User searches for "Metabolic Syndrome" again.
PROMPT Logic:    1. Vector Search finds "Type 2 Diabetes" is semantically closest.
PROMPT           2. Graph Traversal proceeds from the inferred node.
PROMPT Expectation: SUCCESS (Relevant treatments found via semantic link).
PROMPT ============================================================================
PROMPT

