-- CTE: Find the closest concept in our graph to "Metabolic Syndrome"
WITH semantic_candidates AS (
    SELECT 
        c.node_id,
        c.name AS inferred_condition,
        VECTOR_DISTANCE(
            c.description_embedding, 
            TO_VECTOR(:v_vector_clob), 
            COSINE
        ) AS distance
    FROM 
        conditions_nodes c
    ORDER BY distance ASC
    FETCH FIRST 5 ROWS ONLY
)
SELECT 
    'Metabolic Syndrome' AS user_query,
    sc.inferred_condition AS graph_concept,
    ROUND(sc.distance, 4) AS score,
    t.entity_name AS recommended_treatment
FROM 
    semantic_candidates sc
    -- Now traverse the graph from the INFERRED node(s)
    JOIN treats_edges te ON te.to_node_id = sc.node_id
    JOIN treatments_nodes t ON t.node_id = te.from_node_id
ORDER BY 
    sc.distance ASC, t.entity_name
FETCH FIRST 20 ROWS ONLY;

PROMPT ============================================================================
PROMPT CONCLUSION:
PROMPT The Graph layer provided the structure (Treatments exist).
PROMPT The Vector layer provided the flexibility (Metabolic Syndrome ~= Diabetes).
PROMPT ============================================================================
